INSERT INTO public.stories (id, title, author, genre, estimated_time, total_parts) VALUES ('11111111-1111-1111-1111-111111111111', 'There''s an Alligator Under My Bed', 'Mercer Mayer', 'Children', '10 mins', 14) ON CONFLICT (id) DO NOTHING;

-- Data for story_pages (14 rows)
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('d5d95b4c-6cc2-45e2-88c8-689d39c2a6c0', '11111111-1111-1111-1111-111111111111', 1, '/images/alligator-page-1.png', '/images/alligator-page-2.png', 'There used to be an alligator under my bed.', 'Oh wow, look at his face! Why is he carrying that big wooden board into his room?', 'How do you think the boy feels about going to bed when he believes an alligator is under there?', 'He probably feels scared and worried that the alligator will get him!', '2026-11-17T17:30:58.37303+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('7aaa9831-9fa1-45ed-9706-fc9b33ae44f0', '11111111-1111-1111-1111-111111111111', 2, '/images/alligator-page-3.png', '/images/alligator-page-4.png', 'When it was time to go to sleep, I had to be very careful because I knew he was there.', 'Whoa! He used the board like a bridge so his feet wouldn''t touch the floor!', 'Why do you think the boy has to be very careful?', 'Because he is afraid the alligator might bite his toes if he steps on the floor!', '2026-11-17T17:30:58.37303+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('02a104eb-b9dc-4ea7-a505-c0d5ad3f110b', '11111111-1111-1111-1111-111111111111', 3, '/images/alligator-page-5.png', '/images/alligator-page-6.png', 'But whenever I looked, he hid... or something. So I''d call Mom and Dad.', 'That sneaky alligator hid right when he looked! No wonder he is yelling for his parents!', 'How do you think the boy feels when he looks under the bed and can''t see the alligator?', 'He feels nervous and wants his parents to come protect him.', '2026-11-17T17:30:58.37303+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('e56788d0-06c6-4611-99ae-2f36cbe8c58e', '11111111-1111-1111-1111-111111111111', 4, '/images/alligator-page-7.png', '/images/alligator-page-8.png', 'But they never saw it. It was up to me. I just had to do something about that alligator.', 'Grown-ups never see the monsters! Look how brave he is climbing out of bed by himself!', 'What are Mom and Dad thinking when they look under the bed?', 'They think he is just imagining things and that there is no alligator.', '2026-11-17T17:30:58.37303+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('1ba6fef0-eb5a-401f-88f5-2d0d994acdaf', '11111111-1111-1111-1111-111111111111', 5, '/images/alligator-page-9.png', '/images/alligator-page-10.png', 'So I went to the kitchen to get some alligator bait.', 'Ooh, he is getting all kinds of yummy food from the fridge!', 'What is the boy planning to do with the alligator bait?', 'He wants to trick the hungry alligator into coming out from under his bed.', '2026-11-17T17:30:58.37303+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('6a4080b5-cfa2-4f79-8085-ab5e2510ca16', '11111111-1111-1111-1111-111111111111', 6, '/images/alligator-page-11.png', '/images/alligator-page-12.png', 'I put a peanut butter sandwich, some fruit, and the last piece of pie in the garage.', 'Look at his proud little smile! He is setting up a yummy trap in the garage!', 'Why did the boy decide to put the food all the way in the garage?', 'Because he wants to lure the alligator all the way out of the house!', '2026-11-17T17:35:26.069227+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('1ef05345-1d6f-43f7-a70f-237190c74b5e', '11111111-1111-1111-1111-111111111111', 7, '/images/alligator-page-13.png', '/images/alligator-page-14.png', 'I put cookies down the hall. I left fresh vegetables on the stairs.', 'Hehehe! He is making a whole trail of snacks down the stairs!', 'What does the boy think the alligator will do when it sees this trail of food?', 'He thinks the alligator will follow the snacks step by step down the stairs.', '2026-11-17T17:35:26.249654+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('e5ff454c-0183-4550-b9be-e11eaa28a49d', '11111111-1111-1111-1111-111111111111', 8, '/images/alligator-page-15.png', '/images/alligator-page-16.png', 'I put a soda and some candy next to my bed. Then I watched and waited. Sure enough, out he came to get something to eat.', 'Whoa, it worked! The alligator is coming right out for the candy and soda!', 'How do you think the boy feels as he watches the alligator finally crawl out?', 'He probably feels a little nervous, but also excited that his smart plan is working!', '2026-11-17T17:35:26.423941+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('fa2415e1-b010-4f7a-b9b9-d34d035b6eb0', '11111111-1111-1111-1111-111111111111', 9, '/images/alligator-page-17.png', '/images/alligator-page-18.png', 'Then I hid in the hall closet. I followed him down the stairs.', 'Hehehe, look at the boy peeking out from the closet door!', 'Why did the boy hide in the closet while the alligator walked by?', 'Because he didn''t want the alligator to see him and get scared away or chase him.', '2026-11-17T17:35:26.568069+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('c06f3d90-b0cb-4b78-bc3b-b846f425e65e', '11111111-1111-1111-1111-111111111111', 10, '/images/alligator-page-19.png', '/images/alligator-page-20.png', 'I followed him down the hall.', 'Look at the alligator''s happy face while he munches those cookies!', 'How is the alligator feeling right now as he eats the trail of cookies?', 'The alligator feels super happy and hungry, and has no idea he is walking into a trap!', '2026-11-17T17:35:26.725457+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('dc619b27-e078-412d-8e65-6d1471257a99', '11111111-1111-1111-1111-111111111111', 11, '/images/alligator-page-21.png', '/images/alligator-page-22.png', 'When he crawled into the garage,', 'Ooh! The alligator is crawling right into the garage! Look at the boy hiding behind the door!', 'What is the boy waiting and hoping for as he hides behind the garage door?', 'He is waiting for the alligator''s tail to go all the way inside so he can shut the door!', '2026-11-17T17:35:27.003187+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('7c62ddb6-6058-4969-af53-5384cefe3de1', '11111111-1111-1111-1111-111111111111', 12, '/images/alligator-page-23.png', '/images/alligator-page-24.png', 'I slammed the door and locked it. Then I went to bed. There wasn''t even any mess to clean up.', 'Yay! Look at him throwing his hands up in the air! He did it!', 'How does the boy feel right after locking the alligator in the garage?', 'He feels super proud, relieved, and happy that his room is finally safe!', '2026-11-17T17:35:27.154301+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('05d3211b-1f76-4b27-a8e8-ab8aa741fcb9', '11111111-1111-1111-1111-111111111111', 13, '/images/alligator-page-25.png', '/images/alligator-page-26.png', 'Now that there is an alligator in the garage, I wonder if my dad will have any trouble getting in his car tomorrow morning.', 'Uh-oh! He doesn''t need his wooden board anymore, but now the alligator is by Dad''s car!', 'What is the boy worried might happen to his dad in the morning?', 'He is worried that his dad will be surprised or scared by the alligator in the garage!', '2026-11-17T17:35:27.317679+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.story_pages (id, story_id, page_number, left_image_url, right_image_url, page_text, avatar_comment, mst_prompt, mst_response, created_at) VALUES ('4e6443da-90ce-40dc-b0c0-792fdb4436de', '11111111-1111-1111-1111-111111111111', 14, '/images/alligator-page-27.png', '/images/alligator-page-27.png', 'I''ll just leave him a note. "DEAR DAD, THERE IS AN ALLIGATOR IN THE GARAGE. IF YOU NEED HELP WAKE ME UP. WARNING BE CAREFUL."', 'Hehehe! Look at the funny picture and warning note he taped to the door for his dad!', 'Why did the boy leave a note offering to help his dad?', 'Because he loves his dad, wants to warn him to be careful, and feels brave enough to help!', '2026-11-17T17:35:27.472194+00:00') ON CONFLICT (id) DO NOTHING;

