INSERT INTO public.session_logs (id, session_id, page_id, participation_id, story_page_text, transcript, mst_detected, mst_analysis, child_response, conversation_summary, created_at, question_text, emotion_match, follow_up_question) VALUES ('785348c6-a17c-44f7-b320-b8b58558bef7', 'ab5735d8-b2b5-46fb-8902-bacf7553675d', '1cdfe9a4-93c3-4330-8549-ae91efc9b8b3', 'test', 'It was up to me. I just had to leave him some bait.', 'he is going to catch the alligator hes very brave', TRUE, 'The reader states that the character is "very brave," which is a feeling or emotional state. By attributing this trait to the character''s action of going to catch the alligator, the reader is interpreting the character''s internal state and emotional response to the situation.', 'He is so brave! I love the bait idea!', 'The reader noted that the character intends to catch the alligator and is very brave. The child expressed enthusiasm for the character''s bravery and specifically praised the bait idea.', '2026-10-12T04:51:00.003644+00:00', 'What are Mom and Dad thinking when they look under the bed?', 'CORRECT', NULL) ON CONFLICT (id) DO NOTHING;
